pub struct BayesianInference {
    prior_probabilities: HashMap<String, f64>,
    likelihoods: HashMap<String, HashMap<String, f64>>,
}

impl BayesianInference {
    pub fn new() -> Self {
        BayesianInference {
            prior_probabilities: HashMap::new(),
            likelihoods: HashMap::new(),
        }
    }

    pub fn update_prior(&mut self, sensor_id: &str, probability: f64) {
        self.prior_probabilities.insert(sensor_id.to_string(), probability);
    }

    pub fn update_likelihood(&mut self, sensor_id: &str, value: &str, probability: f64) {
        self.likelihoods.entry(sensor_id.to_string())
            .or_insert_with(HashMap::new)
            .insert(value.to_string(), probability);
    }

    pub fn calculate_posterior(&self, sensor_id: &str, evidence: &str) -> f64 {
        let prior = *self.prior_probabilities.get(sensor_id).unwrap_or(&0.5);
        let likelihood = *self.likelihoods.get(sensor_id)
            .and_then(|m| m.get(evidence))
            .unwrap_or(&0.5);

        // Simple Bayesian update (Bayes' theorem)
        (likelihood * prior) / (likelihood * prior + (1.0 - likelihood) * (1.0 - prior))
    }
}
